// Expects {"image": "emqx/emqx:6.3.2"} -- called by process-candidate.py (docker-update-check).
const body = $input.item.json.body ?? $input.item.json;
const imageRef = body.image || '';

let refPart = imageRef;
let tag = 'latest';
const lastColon = imageRef.lastIndexOf(':');
const lastSlash = imageRef.lastIndexOf('/');
if (lastColon > lastSlash) {
  refPart = imageRef.substring(0, lastColon);
  tag = imageRef.substring(lastColon + 1);
}

let pathParts = refPart.split('/');
if (pathParts[0].includes('.') || pathParts[0] === 'docker.io') {
  pathParts = pathParts.slice(1);
}
const repoPath = pathParts.join('/');

return [{ json: { image: imageRef, tag, repoPath } }];

// Known Docker image paths -> GitHub repo. Extend as needed
// when a new service is added to config/versions.yaml.
const map = {
  'envoyproxy/envoy': { owner: 'envoyproxy', repo: 'envoy' },
  'postgrest/postgrest': { owner: 'PostgREST', repo: 'postgrest' },
  'supabase/gotrue': { owner: 'supabase', repo: 'auth' },
  'supabase/postgres-meta': { owner: 'supabase', repo: 'postgres-meta' },
  'supabase/realtime': { owner: 'supabase', repo: 'realtime' },
  'emqx/emqx': { owner: 'emqx', repo: 'emqx' },
  'influxdb': { owner: 'influxdata', repo: 'influxdb' },
  'library/influxdb': { owner: 'influxdata', repo: 'influxdb' },
  'louislam/uptime-kuma': { owner: 'louislam', repo: 'uptime-kuma' },
  'dongdongbh/mindwtr-cloud': { owner: 'dongdongbh', repo: 'Mindwtr' },
  'traefik': { owner: 'traefik', repo: 'traefik' },
  'grafana/grafana': { owner: 'grafana', repo: 'grafana' },
  'grafana/loki': { owner: 'grafana', repo: 'loki' },
  'goauthentik/server': { owner: 'goauthentik', repo: 'authentik' },
  'gitea/gitea': { owner: 'go-gitea', repo: 'gitea' },
  'hashicorp/vault': { owner: 'hashicorp', repo: 'vault' },
  'vaultwarden/server': { owner: 'dani-garcia', repo: 'vaultwarden' },
  'n8nio/n8n': { owner: 'n8n-io', repo: 'n8n' },
  'crazymax/diun': { owner: 'crazy-max', repo: 'diun' },
  'kestra/kestra': { owner: 'kestra-io', repo: 'kestra' },
  'adguard/adguardhome': { owner: 'AdguardTeam', repo: 'AdGuardHome' },
  'library/redis': { owner: 'redis', repo: 'redis' },
  'redis': { owner: 'redis', repo: 'redis' },
  'library/nextcloud': { owner: 'nextcloud', repo: 'server' },
  'nextcloud': { owner: 'nextcloud', repo: 'server' }
};

const item = $input.item.json;
const hit = map[item.repoPath] || null;

return [{
  json: {
    ...item,
    githubOwner: hit ? hit.owner : null,
    githubRepo: hit ? hit.repo : null
  }
}];

const items = $input.all();
let releases;
if (items.length === 1 && Array.isArray(items[0].json)) {
  releases = items[0].json;
} else {
  releases = items.map(i => i.json);
}

const top = releases.slice(0, 3);
const notes = top
  .map(r => `## ${r.tag_name || r.name || '?'}\n${(r.body || '(keine Release-Notes)').slice(0, 1500)}`)
  .join('\n\n---\n\n');

const ctx = $('Image zu GitHub-Repo mappen').item.json;

return [{
  json: {
    ...ctx,
    releaseNotes: notes || '(keine Release-Notes gefunden)'
  }
}];

