const ctx = $('Release-Notes formatieren').item.json;
const claude = $input.item.json;
const summary = claude.content && claude.content[0] ? claude.content[0].text : null;
return [{ json: { mapped: true, repo: ctx.githubOwner + '/' + ctx.githubRepo, tag: ctx.tag, summary } }];
